    @Test
    void theCorporateRateNeedsTheCodeOfAKnownCompany() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(corporate(101, "2027-03-10", "2027-03-12", null))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(corporate(101, "2027-03-10", "2027-03-12", "METALSUL"))));
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(corporate(101, "2027-03-10", "2027-03-12", "tecnosul"))));

        Reservation reservation = service.create(corporate(201, "2027-03-10", "2027-03-12", "TECNOSUL"));

        assertEquals(new BigDecimal("93.58"), reservation.price().discount());
        assertEquals(new BigDecimal("686.22"), reservation.price().total());
    }

    @Test
    void theWeekendPackageOnlyGoesFromFridayToSunday() {
        assertEquals(ErrorCode.INVALID_REQUEST, // a Saturday
                errorOf(() -> service.create(stay(101, "2027-03-13", "2027-03-15", 1, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST, // a Friday, but three nights
                errorOf(() -> service.create(stay(101, "2027-03-12", "2027-03-15", 1, RatePlan.WEEKEND_PACKAGE))));

        Reservation reservation = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));

        assertEquals(new BigDecimal("820.00"), reservation.price().total());
    }

    @Test
    void theLongStayNeedsSevenNights() {
        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> service.create(stay(101, "2027-03-01", "2027-03-07", 1, RatePlan.LONG_STAY))));

        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 1, RatePlan.LONG_STAY));

        assertEquals(new BigDecimal("1749.30"), reservation.price().subtotal());
        assertEquals(new BigDecimal("174.93"), reservation.price().discount());
        assertEquals(new BigDecimal("1574.37"), reservation.price().total());
    }

    @Test
    void cancellingTheNewPlansGivesBackWhatEachOnePromises() {
        Reservation corporate = service.create(corporate(101, "2027-03-10", "2027-03-12", "TECNOSUL"));
        Reservation weekendPackage = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
        Reservation longStay = service.create(stay(301, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));
        service.confirm(corporate.id());
        service.confirm(weekendPackage.id());
        service.confirm(longStay.id());

        assertEquals(new BigDecimal("686.22"), service.cancel(corporate.id()).refund());
        assertEquals(new BigDecimal("410.00"), service.cancel(weekendPackage.id()).refund());
        assertEquals(longStay.price().total(), service.cancel(longStay.id()).refund());
        // half of the package stays with the inn
        assertEquals(new BigDecimal("410.00"), weekendPackage.amountKept());
        assertEquals(new BigDecimal("0.00"), corporate.amountKept());
    }

    @Test
    void aPendingReservationOnThePackageNeverPaid() {
        Reservation weekendPackage = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));

        assertEquals(new BigDecimal("0.00"), service.cancel(weekendPackage.id()).refund());
    }
}
