    @Test
    void booksOnACorporateDeal() throws Exception {
        String body = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "checkIn": "2027-03-10", "checkOut": "2027-03-12",
                 "guests": 2, "ratePlan": "CORPORATE", "companyCode": "TECNOSUL"}
                """;

        HttpResponse<String> created = post("/reservations", body);

        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        assertEquals(779.80, reservation.get("subtotal").asDouble());
        assertEquals(93.58, reservation.get("discount").asDouble());
        assertEquals(686.22, reservation.get("total").asDouble());

        // without a company we have a deal with, the reservation cannot be made
        HttpResponse<String> unknownCompany = post("/reservations", body.replace("TECNOSUL", "METALSUL"));
        assertEquals(400, unknownCompany.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(unknownCompany.body()).get("error").asText());
    }

    @Test
    void booksTheWeekendPackageAndRefundsHalfOfIt() throws Exception {
        String body = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "checkIn": "2027-03-12", "checkOut": "2027-03-14",
                 "guests": 2, "ratePlan": "WEEKEND_PACKAGE"}
                """;

        HttpResponse<String> created = post("/reservations", body);
        assertEquals(201, created.statusCode());
        long id = json.readTree(created.body()).get("id").asLong();
        assertEquals(820.00, json.readTree(created.body()).get("total").asDouble());

        post("/reservations/" + id + "/confirmation", "");
        HttpResponse<String> cancelled = post("/reservations/" + id + "/cancellation", "");

        assertEquals(410.00, json.readTree(cancelled.body()).get("refund").asDouble());

        // any other date is not a weekend package
        assertEquals(400, post("/reservations", body.replace("2027-03-14", "2027-03-15")).statusCode());
    }

    @Test
    void ignoresTheCompanyCodeOnTheOtherPlans() throws Exception {
        HttpResponse<String> created = post("/reservations",
                RESERVATION_JSON.replace("\"ratePlan\": \"STANDARD\"", "\"ratePlan\": \"STANDARD\", \"companyCode\": \"TECNOSUL\""));

        assertEquals(201, created.statusCode());
        assertEquals(935.76, json.readTree(created.body()).get("total").asDouble());
    }
}
EOF
